bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
import {createGateOwner} from '/opt/videobot/owner/gateOwner.mjs';
import {createPostgresPostingReceiptStore} from '/opt/videobot/src/sales/pgPostingReceipts.mjs';
import {createPostgresListingStore} from '/opt/videobot/src/sales/pgListings.mjs';
import {publishVideoListing} from '/opt/videobot/src/telegram/paidListingPublisher.mjs';
const id='389558ba-a38b-42a1-b92e-e98143df3e2d';
const token=readFileSync(process.env.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
const url=readFileSync(process.env.VIDEOBOT_DATABASE_URL_FILE,'utf8').trim();
const pool=new pg.Pool({connectionString:url,max:2,connectionTimeoutMillis:5000});
try {
 const api=createTelegramBotApi({token,timeoutMs:25000});
 const gate=await createGateOwner({telegramApi:api,pool,env:process.env});
 const row=await pool.query("SELECT seller_user_id FROM videobot_listings WHERE listing_id=$1 AND status='draft' AND rights_verified=TRUE AND adult_consent_verified=TRUE AND fee_terms_accepted_at IS NOT NULL AND management_fee_bps=3000 AND price_stars>0 AND thumbnail_file_id IS NOT NULL AND sample_file_id IS NOT NULL AND paid_video_file_id IS NOT NULL",[id]);
 if(row.rowCount!==1)throw Error('VIDEO_DRAFT_NOT_READY_OR_NOT_UNIQUE');
 const seller=Number(row.rows[0].seller_user_id);
 const listings=createPostgresListingStore(pool);
 const listing=await listings.getOwned(seller,id);
 if(!listing||listing.revision<1)throw Error('VIDEO_LISTING_OWNER_OR_REVISION_INVALID');
 const key=listing.id+':'+listing.revision;
 const receipts=createPostgresPostingReceiptStore(pool);
 const old=await receipts.read(key);
 if(old){
  if(old.status==='sent'&&Number.isSafeInteger(old.paidMessageId)){console.log('VIDEO_ALREADY_SENT_PAID_MESSAGE_ID='+old.paidMessageId);process.exitCode=0;}
  else throw Error('VIDEO_EXISTING_RECEIPT_RECONCILIATION_REQUIRED');
 }else{
  const topic=await gate.getVerifiedVideoTopic({purpose:'video_sale',sellerId:listing.sellerId,listingId:listing.id});
  if(topic.chatId!==-1002373696859||topic.threadId!==1695||topic.purpose!=='video_sale')throw Error('VIDEO_TOPIC_IDENTITY_MISMATCH');
  if(await gate.verifyMembership({sellerId:listing.sellerId,chatId:topic.chatId})!==true)throw Error('VIDEO_SELLER_NOT_MEMBER');
  if(await gate.verifyReview({sellerId:listing.sellerId,listingId:listing.id,revision:listing.revision})!==true)throw Error('VIDEO_LISTING_REVIEW_NOT_READY');
  if(await gate.verifyRelease({purpose:'video_sale',chatId:topic.chatId,threadId:topic.threadId})!==true)throw Error('VIDEO_TOPIC_RELEASE_NOT_READY');
  const result=await publishVideoListing({
    listing:{...listing,ownerConfirmedPublish:true},
    getVerifiedVideoTopic:gate.getVerifiedVideoTopic,
    verifyMembership:gate.verifyMembership,
    verifyReview:gate.verifyReview,
    verifyRelease:gate.verifyRelease,
    store:receipts,
    telegramApi:api
  });
  if(result.posted!==true||!Array.isArray(result.freeMessageIds)||result.freeMessageIds.length!==2||!Number.isSafeInteger(result.paidMessageId))throw Error('VIDEO_TELEGRAM_ACK_NOT_COMPLETE');
  await listings.markPublished(seller,id,listing.revision,result);
  const check=await pool.query("SELECT status FROM videobot_listings WHERE listing_id=$1",[id]);
  if(check.rows[0]?.status!=='published')throw Error('VIDEO_PUBLISH_DB_READBACK_FAILED');
  console.log('VIDEO_PUBLISHED_TOPIC=1695');
  console.log('VIDEO_FREE_MESSAGE_IDS='+result.freeMessageIds.join(','));
  console.log('VIDEO_PAID_MESSAGE_ID='+result.paidMessageId);
  console.log('VIDEO_PUBLISHED_READBACK=PASS');
 }
}finally{await pool.end()}
NODE
